def time_to_minutes(time_str):
    """Chuyển đổi thời gian HH:MM thành số phút"""
    hours, minutes = map(int, time_str.split(':'))
    return hours * 60 + minutes
def main():
    n = int(input())
    station_data = {}
    station_order = []
    for _ in range(n):
        ten = input().strip()
        start_time = input().strip()
        end_time = input().strip()
        luong_mua = int(input())
        start_minutes = time_to_minutes(start_time)
        end_minutes = time_to_minutes(end_time)
        duration = end_minutes - start_minutes
        if ten not in station_data:
            station_data[ten] = {
                'total_duration': duration,
                'total_rain': luong_mua
            }
            station_order.append(ten)
        else:
            station_data[ten]['total_duration'] += duration
            station_data[ten]['total_rain'] += luong_mua
    for idx, ten in enumerate(station_order, 1):
        total_duration = station_data[ten]['total_duration']
        total_rain = station_data[ten]['total_rain']
        if total_duration > 0:
            avg_rain = (total_rain * 60) / total_duration
        else:
            avg_rain = 0.0
        station_id = f"T{idx:02d}"
        print(f"{station_id} {ten} {avg_rain:.2f}")
if __name__ == "__main__":
    main()

